function testShiftingToEmptyDoesNotBreakTheList() {
    LinkedList list = newLinkedList();
    push(list, 41);
    push(list, 59);
    _ = shift(list);
    _ = shift(list);
    push(list, 47);
    test:assertEquals(count(list), 1);
    test:assertEquals(shift(list), 47);
}

